  (function () {
    if (window.__klaviyoNewsletterInit) return;
    window.__klaviyoNewsletterInit = true;

    var EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    function isMobile() {
      return /Android|iPhone|iPod|webOS|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent) ||
             (navigator.maxTouchPoints > 1 && /Macintosh/.test(navigator.userAgent));
    }

    async function subscribe(cfg) {
      try {
        var res = await fetch(
          'https://a.klaviyo.com/client/subscriptions/?company_id=' + cfg.company,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', revision: '2026-04-15' },
            body: JSON.stringify({
              data: {
                type: 'subscription',
                attributes: {
                  custom_source: cfg.source,
                  profile: {
                    data: {
                      type: 'profile',
                      attributes: {
                        email: cfg.email,
                        subscriptions: { email: { marketing: { consent: 'SUBSCRIBED' } } }
                      }
                    }
                  }
                },
                relationships: { list: { data: { type: 'list', id: cfg.listId } } }
              }
            })
          }
        );

        if (res.status === 202) {
          cfg.form.hidden = true;
          if (cfg.success) cfg.success.hidden = false;
          setTimeout(function () {
            window.location.href = isMobile()
              ? 'https://www.instagram.com/zigzagworld/'
              : '/';
          }, 2000);
        } else {
          cfg.reset();
          var detail = await res.text();
          console.warn('Klaviyo signup: status', res.status, detail);
        }
      } catch (err) {
        cfg.reset();
        console.error('Klaviyo signup error', err);
      }
    }

    function initForms() {
      document.querySelectorAll('.klaviyo-newsletter').forEach(function (root) {
        if (root.dataset.klaviyoBound) return;
        root.dataset.klaviyoBound = '1';

        var form = root.querySelector('form');
        if (!form) return;
        var success = root.querySelector('.newsletter-form__success');
        var submitting = false;

        form.addEventListener('submit', function (e) {
          e.preventDefault();
          e.stopImmediatePropagation();
          if (submitting) return;

          var input = form.querySelector('input[type="email"]');
          var email = (input ? input.value : '').trim();
          if (!EMAIL_REGEX.test(email)) return;

          submitting = true;
          subscribe({
            email: email,
            company: root.dataset.klaviyoCompany,
            listId: root.dataset.klaviyoList,
            source: root.dataset.klaviyoSource || 'Newsletter signup',
            form: form,
            success: success,
            reset: function () { submitting = false; }
          });
        }, true);
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initForms);
    } else {
      initForms();
    }
    document.addEventListener('shopify:section:load', initForms);
  })();

















