"navigationBannerTextColor":"#ffffff","navigationBannerStepDoneColor":"#FFFFFF"},"previewPage":{"bannerTextColor":"#ffffff"},"primaryFont":"","productCard":{"productCardBgColor":"#ffffff","cardBorderRadius":"10px","cardImageBorderRadius":"8px","productImageFit":"cover","cardsPerRowXL":4,"cardsPerRowL":4,"productCardTextColor":"#252525","productTitleFontSize":"16px","productTitleFontWeight":"Bold","productPriceVisibility":"Show","compareAtPriceColor":"#8D8D8D","compareAtPriceFontSize":"14px","compareAtPriceFontWeight":"Bold","compareAtPriceVisibility":"Show","finalPriceFontSize":"16px","finalPriceFontColor":"#252525","finalPriceFontWeight":"Bold","productCardButtonColor":"#000000","productCardButtonTextColor":"#ffffff","buttonBorderRadius":"10px","quantitySelectorTextColor":"#000000","allowOnlyOneQuantity":false,"quantitySelectorBgColor":"#000000","productCardQuantitySelectorBgColor":"#eeeeee","quantitySelectorButtonTextColor":"#FFFFFF","quantitySelectorButtonBorderRadius":"6px","productCardVariantSelectorFontSize":"14px","productCardVariantSelectorFontWeight":"Regular"},"quickSettings":{"isQuickSettingsEnabled":true,"colors":{"primaryColor":"#000000","buttonBgColor":"#000000","buttonTextColor":"#ffffff"}},"summaryBlock":{"summaryBlockAddToCartButtonColor":"#000000","summaryBlockAddToCartButtonTextColor":"#ffffff","summaryBlockBackButtonColor":"#252525","summaryBlockBackButtonTextColor":"#ffffff","summaryBuildNewBoxButtonColor":"#6d7175","summaryBuildNewBoxTextColor":"#ffffff"},"updatedAt":"2026-06-29T08:44:32.683Z","productBundle":{"designSettings":{},"globalSettings":{"general":{"autoShiftToAvailableVariant":true,"hideOutOfStockOptions":false,"unselectOptionsByDefault":true,"showProductCardImageBorder":true,"footerSavingPillPosition":"BEFORE_PRICE","metafieldNameSpaceAndKeys":[],"isB2BCatalogPricingEnabled":false,"allowPartialLocaleMatching":false,"productImageTransformConfig":{"isEnabled":true,"options":"{ maxHeight: 400, maxWidth: 400, scale: 1 }"},"customCss":"","customJs":""},"devMode":{"useNativeCartRefresh":true,"useWidgetATCButton":true,"useShadowRoot":false,"useAcceleratedCheckoutUrlRedirect":true,"useFormOnlyCartAdd":false},"selectorConfig":{"productFormSubmitSelector":null,"customVariantPickerSelectors":null,"quantityBtnSelectors":null,"addToCartBtnSelectors":null,"checkoutBtnSelector":null,"nativeDiscountedPriceSelector":null,"nativeOriginalPriceSelector":null,"nativePriceBadgeSelector":null},"postDecisionAddToCartConfig":{"executeDefaultSideCartUpdate":false,"redirectToCheckoutEnabled":true,"redirectToCartEnabled":false,"executeScriptAfterAddToCart":""}}}}};
            let parent_product_data = null;

            if(full_page_ext_data && !full_page_ext_data?.errorMsg) {
                window.easybundle_user_ext_data = full_page_ext_data.userData || {}
            }

            if (parent_product_data && !parent_product_data?.errorMsg) {
                window.shopifyLiquidValuesApp4Ext.product.bundleProductConfiguration = parent_product_data;

                const isAutoPlaceFullPageBundleEnabled = full_page_ext_data?.userData?.customSettings?.isAutoPlaceFullPageBundleEnabled ?? true
                let bundle_data = null;
                const keys = ["SDK", "PB"];
                const keyPrefix = parent_product_data.appLevelMetafieldKey?.split('-')[0];
                const isSdkBundle = keys.includes(keyPrefix);

                // PDP/PB/QB bundles render alongside the product; only full-page bundles wipe the main wrapper.
                const bundleDesignTemplate = parent_product_data.bundleDesignTemplate || '';
                const isPdpBundleBuilder = bundleDesignTemplate.startsWith('PDP_') || bundleDesignTemplate === 'CUSTOM_TEMPLATE';
                const isPbBundleBuilder = bundleDesignTemplate.startsWith('PB_');
                const isQbBundleBuilder = bundleDesignTemplate.startsWith('QB_');
                const isPdpBundle = isPdpBundleBuilder || isPbBundleBuilder || isQbBundleBuilder;


                if(full_page_ext_data && bundle_data){

                    if (!isPdpBundle){
                            isAutoPlaceFullPageBundleEnabled && removeProductHtmlForBundles();
                            isAutoPlaceFullPageBundleEnabled && buildDummyProductHtmlForBundles();
                    }
                    const discountsConfiguration = bundle_data?.discountsData;
                    delete bundle_data.discountsData;
                    let active_bundle_data = {
                        ...full_page_ext_data,
                        stepsConfigurationData: bundle_data,
                        discountsData: discountsConfiguration || {},
                    }

                    // SDK bundles read _bundleData only — drop the legacy stepsConfigurationData copy.
                    if (isSdkBundle) {
                        active_bundle_data.bundleType = parent_product_data.bundleType,
                        active_bundle_data.bundleDesignTemplate = parent_product_data.bundleDesignTemplate,
                        active_bundle_data._preResolvedBundle = true,
                        active_bundle_data._bundleData = bundle_data,
                        delete active_bundle_data.stepsConfigurationData;
                    }

                    // Canonical name; easybundle_full_page_ext_data is a legacy alias (same reference).
                    window.easybundle_active_bundle_data = active_bundle_data;
                    window.easybundle_full_page_ext_data = active_bundle_data;
                }
            }
        }
        // M&M relevancy: parent-product page, or upsell embed/widget display rules match this product/collections.
        function checkIfShouldImportMixAndMatchAssets(allMixAndMatchBundles) {
            try{
                const currentProductId = window.shopifyLiquidValuesApp4Ext?.product?.productData?.id;
                if(!currentProductId || allMixAndMatchBundles?.length <= 0){
                    return false;
                }
                const isThisParentProductPage = allMixAndMatchBundles.some(bundle => bundle.parentProductShopifyData?.id == currentProductId);
                if(isThisParentProductPage) return true;
                const currentProductCollections = window.shopifyLiquidValuesApp4Ext?.product?.collections?.map(collection => collection.id);
                for(let bundle of allMixAndMatchBundles){
                    const bundleUpsellConfig = bundle.bundleUpsellConfig;
                    const isBundleUpsellEmbedEnabled = bundleUpsellConfig?.upsellConfiguration?.isEnabled;
                    const isBundleUpsellWidgetEnabled = bundleUpsellConfig?.widgetConfiguration?.isEnabled;
                    if(!isBundleUpsellEmbedEnabled && !isBundleUpsellWidgetEnabled) continue;

                    const widgetDisplayConfig = bundleUpsellConfig?.widgetConfiguration?.displayConfiguration;
                    const upsellDisplayConfig = bundleUpsellConfig?.upsellConfiguration?.displayConfiguration;

                    let showOnAllBundleProducts = false;
                    let productIdsToCheck = [];
                    let collectionIdsToCheck = [];

                    if(isBundleUpsellEmbedEnabled){
                        showOnAllBundleProducts = upsellDisplayConfig?.showOnAllBundleProducts;
                        productIdsToCheck = upsellDisplayConfig?.showOnSpecificProductPages?.map(product => product?.productId) || []
                        collectionIdsToCheck = upsellDisplayConfig?.showOnSpecificCollectionPages?.map(collection => collection?.collectionId) || []
                    }

                    if(isBundleUpsellWidgetEnabled){
                        showOnAllBundleProducts = showOnAllBundleProducts || widgetDisplayConfig?.showOnAllBundleProducts;
                        const productIds = widgetDisplayConfig?.showOnSpecificProductPages?.map(product => product?.productId) || [];
                        const collectionIds = widgetDisplayConfig?.showOnSpecificCollectionPages?.map(collection => collection?.collectionId) || [];
                        productIdsToCheck = [ ...productIdsToCheck, ...productIds ];
                        collectionIdsToCheck = [ ...collectionIdsToCheck, ...collectionIds ];
                    }

                    if(showOnAllBundleProducts){
                        Object.keys(bundle ?? {}).filter(key => key?.startsWith('productsData')).forEach(stepKey => {
                            const stepData = bundle?.[stepKey];
                            Object.values(stepData?.categories ?? {}).forEach(category => {
                                const productIds = category?.products?.map(product => product.productId) || [];
                                const collectionIds = category?.collectionsSelectedData?.map(collection => collection.id?.replace("gid://shopify/Collection/", "")) || [];
                                productIdsToCheck = [ ...productIdsToCheck,  ...productIds ];
                                collectionIdsToCheck = [ ...collectionIdsToCheck, ...collectionIds ];
                            })
                        })  
                    }
                    const isThisProductRelevant = productIdsToCheck?.some(productId => productId == currentProductId);    
                    const isThisProductCollectionsRelevant = collectionIdsToCheck?.some(collectionId => currentProductCollections?.includes(collectionId));
                    if(isThisProductRelevant || isThisProductCollectionsRelevant) return true;
                }
                return false;
            }catch(err){
                debugConsole("error in checkIfShouldImportMixAndMatchAssets",err)
                return false;
            }
        }
        window.gbbExtEmbed.f.checkIfShouldImportMixAndMatchAssets = checkIfShouldImportMixAndMatchAssets;

        // Backward-compat JS fallback for SDK upsell matching — primary runs server-side in sdk-upsell-matches.liquid.
        function checkIfShouldImportSDKAssets(allSdkBundles){
            try{
                const matched = [];
                const currentProductId = window.shopifyLiquidValuesApp4Ext?.product?.productData?.id;
                if(!currentProductId || !Array.isArray(allSdkBundles) || allSdkBundles.length <= 0){
                    return matched;
                }
                const currentCollectionIds = window.shopifyLiquidValuesApp4Ext?.product?.collections?.map(c => c.id) ?? [];

                const matchesSurface = (surface) => {
                    if((surface?.productIds ?? []).some(id => id == currentProductId)){
                        return true;
                    }
                    if((surface?.collectionIds ?? []).some(cid => currentCollectionIds.includes(cid))){
                        return true;
                    }
                    return false;
                };

                for(const bundle of allSdkBundles){
                    if(bundle?.bundleStatus && bundle.bundleStatus !== 'ACTIVE') continue;

                    if(bundle?.productId && bundle.productId == currentProductId){
                        matched.push(bundle);
                        continue;
                    }

                    const cfg = bundle?.bundleUpsellConfig;
                    if(!cfg) continue;

                    if(matchesSurface(cfg?.upsellConfiguration?.showOn) || matchesSurface(cfg?.widgetConfiguration?.showOn)){
                        matched.push(bundle);
                    }
                }
                return matched;
            }catch(err){
                debugConsole("error in checkIfShouldImportSDKAssets", err);
                return [];
            }
        }
        window.gbbExtEmbed.f.checkIfShouldImportSDKAssets = checkIfShouldImportSDKAssets;
        function loadAssetFiles(assets){
            try{
                assets.forEach(({ id, tag, attrs, onload }) => {
                    if (!document.getElementById(id)) {
                        const el = Object.assign(document.createElement(tag), { id, ...attrs });
                        const rewriteAssetUrl = window.__ebAssetUrlRewriter;       // preview-only hook; undefined in prod → no-op
                        if (rewriteAssetUrl) {
                            if (el.src) el.src = rewriteAssetUrl(el.src);
                            if (el.href) el.href = rewriteAssetUrl(el.href);
                        }
                        if (onload) el.onload = () => onload(el);
                        document.head.appendChild(el);
                    }
                });
            }catch(err){
                debugConsole("error in loadAssetFiles",err)
            }
        }
        async function importAppEmbedAssets (loadUnminifiedFiles){
            try{
                const jsBaseUrl = loadUnminifiedFiles ? 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/giftBoxLogicv1.js' : 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-min.js';
                const cssBaseUrl = loadUnminifiedFiles ? 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/giftBoxv1.css' : 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-min.css';
                const assets = [
                    {   id: 'gbbExt-bundle-embed-css',
                        tag: 'link', 
                        attrs: { href: cssBaseUrl, rel: 'stylesheet', media: 'all' },
                        onload: (el) => el.media = 'all' 
                    },
                    {   id: 'gbbExt-bundle-embed-js', 
                        tag: 'script',  
                        attrs: { src: jsBaseUrl, async: false, crossOrigin: 'anonymous' }
                    }
                ];
                loadAssetFiles(assets);
            }catch(err){
                debugConsole("error in importAppEmbedAssets",err)
            }
        }
        async function importMixAndMatchAssets (loadUnminifiedFiles){
            try{
                const customSettings = window.easybundles_ext_data?.userData?.customSettings ?? window.easybundle_user_ext_data?.customSettings ?? {};
                const isAutoPlacementEnabled = customSettings?.isLoadMixAndMatchAssetsFromS3Enabled ?? false;
                if(!isAutoPlacementEnabled) return;

                const allMixAndMatchBundles = window.easybundles_ext_data?.mixAndMatchData ?? [];
                const shouldImportMixAndMatchAssets = checkIfShouldImportMixAndMatchAssets(allMixAndMatchBundles);
                if(!shouldImportMixAndMatchAssets) return;

                const baseURL = loadUnminifiedFiles ? 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/mixAndMatchBundle' : 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-product-page-min';
                const assets = [
                    {   id: 'gbbMix-bundle-embed-css',
                        tag: 'link', 
                        attrs: { href: baseURL + '.css', rel: 'stylesheet', media: 'all' },
                        onload: (el) => el.media = 'all' 
                    }, 
                    {   id: 'gbbMix-bundle-embed-js', 
                        tag: 'script',  
                        attrs: { src: baseURL + '.js', async: false, crossOrigin: 'anonymous' }
                    }
                ];
                loadAssetFiles(assets);
            }catch(err){
                debugConsole("error in checkAndImportMixAndMatchScript",err)
            }
        }
        async function importFullPageAssets (loadUnminifiedFiles){
            try{
                const activeBundleData = window.easybundle_active_bundle_data ?? window.easybundle_full_page_ext_data;
                const customSettings = activeBundleData?.userData?.customSettings ?? window.easybundle_user_ext_data?.customSettings ?? {};

                const isAutoPlaceFullPageBundleEnabled = customSettings && (customSettings?.isAutoPlaceFullPageBundleEnabled ?? true);
                if(!isAutoPlaceFullPageBundleEnabled) return; 

                const forceCdn = isForceCdn();
                if(forceCdn || !activeBundleData?.stepsConfigurationData || activeBundleData?.stepsConfigurationData?.errorMsg){
                    debugConsole(forceCdn ? "importFullPageAssets => gbbForceCdn flag set, fetching from backup S3" : "importFullPageAssets => bundleData metafield limit exceeded, fetching from backup S3");
                    const data = await getBundleDataFromS3();
                    if(!data || !data?.stepsConfigurationData){
                        debugConsole("error in importFullPageAssets => Failed to load the backup bundle data from s3.");
                        return;
                    }

                    activeBundleData.stepsConfigurationData = data?.stepsConfigurationData;
                    activeBundleData.discountsData = data?.discountsData;
                }

                const baseURL = loadUnminifiedFiles ? 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-full-page' : 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-full-page-min';
                const assets = [
                    {   id: 'gbb-bundle-embed-css',
                        tag: 'link', 
                        attrs: { href: baseURL + '.css', rel: 'stylesheet', media: 'all' },
                        onload: (el) => el.media = 'all' 
                    },
                    {   id: 'gbb-bundle-embed-js', 
                        tag: 'script',  
                        attrs: { src: baseURL + '.js', async: false, crossOrigin: 'anonymous' }
                    }
                ];
                loadAssetFiles(assets);
            }catch(err){
                debugConsole("error in importFullPageAssets",err)
            }
        }
        // bundleDesignTemplate → template asset URLs (min + dev variants), resolved by Liquid at render time.
        const SDK_TEMPLATE_URLS = {
            PDP_INPAGE: {
                jsMin:  'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inline-bundle.min.js',
                cssMin: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inline-bundle.min.css',
                js:     'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inline-bundle.js',
                css:    'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inline-bundle.css'
            },
            PDP_MODAL: {
                jsMin:  'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/expandable-bundle.min.js',
                cssMin: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/expandable-bundle.min.css',
                js:     'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/expandable-bundle.js',
                css:    'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/expandable-bundle.css'
            },
            FBP_SIDE_FOOTER: {
                jsMin:  'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/side-footer-bundle.min.js',
                cssMin: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/side-footer-bundle.min.css',
                js:     'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/side-footer-bundle.js',
                css:    'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/side-footer-bundle.css'
            },
            PB_CLASSIC_INLINE: {
                jsMin: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inset-bundle.min.js',
                cssMin: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inset-bundle.min.css',
                js: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inset-bundle.js',
                css: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/inset-bundle.css'
            },
            CUSTOM_TEMPLATE: {
                jsMin:  `https://d1712zxri13o2p.cloudfront.net/customTemplates/${window.Shopify.shop}/###TEMPLATE_ID###/bundle.js`,
                cssMin: `https://d1712zxri13o2p.cloudfront.net/customTemplates/${window.Shopify.shop}/###TEMPLATE_ID###/bundle.css`,
                js:     `https://d1712zxri13o2p.cloudfront.net/customTemplates/${window.Shopify.shop}/###TEMPLATE_ID###/bundle.js`,
                css:    `https://d1712zxri13o2p.cloudfront.net/customTemplates/${window.Shopify.shop}/###TEMPLATE_ID###/bundle.css`
            }
        };

        window.SDK_TEMPLATE_URLS = {...(window.SDK_TEMPLATE_URLS ?? {}), ...SDK_TEMPLATE_URLS};
        // Loads SDK runtime + template assets; bundleContext (upsell case) overrides the parent-product metafield.
        // async:false preserves order (SDK before template); template-keyed ids let template types coexist on one page.
        async function importSDKAssets(bundleContext, loadUnminifiedFiles){
            try{
                const parentProductData = window.shopifyLiquidValuesApp4Ext?.product?.bundleProductConfiguration;
                const offerId              = bundleContext?.offerId              ?? parentProductData?.offerId;
                const bundleDesignTemplate = bundleContext?.bundleDesignTemplate ?? parentProductData?.bundleDesignTemplate;
                const templateId = bundleContext?.templateId ?? parentProductData?.templateId;
                const bundleType = bundleContext?.bundleType ?? parentProductData?.bundleType;

                if(!offerId){
                    debugConsole("importSDKAssets: no offerId found in product metafield");
                    return;
                }

                const templateConfig = SDK_TEMPLATE_URLS[bundleDesignTemplate];
                if(!templateConfig){
                    debugConsole("importSDKAssets: no template registered for bundleDesignTemplate", bundleDesignTemplate);
                    return;
                }

                let templateJs  = loadUnminifiedFiles ? templateConfig.js  : templateConfig.jsMin;
                let templateCss = loadUnminifiedFiles ? templateConfig.css : templateConfig.cssMin;

                // Custom templates are published per-template — the URL above has the shop name
                // baked in but a ###TEMPLATE_ID### placeholder; swap it for the selected template id.
                if (bundleDesignTemplate === 'CUSTOM_TEMPLATE') {
                    if (!templateId) {
                        debugConsole("importSDKAssets: CUSTOM_TEMPLATE selected but no templateId in product metafield");
                        return;
                    }
                    templateJs  = templateJs.replace('###TEMPLATE_ID###', templateId);
                    templateCss = templateCss.replace('###TEMPLATE_ID###', templateId);
                }

                // Family-specific runtime: first matching rule wins; last rule is the default (mix SDK).
                const SDK_RUNTIME_RULES = [
                    {   match: (type) => (type || '').includes('PRODUCT_BUNDLE'),
                        id: 'gbb-precurated-sdk-js',
                        url: loadUnminifiedFiles ? 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-pb-sdk.js' : 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-pb-sdk.min.js' },
                    {   match: () => true,
                        id: 'gbb-sdk-js',
                        url: 'https://cdn.shopify.com/extensions/019fdaf2-d5b2-7173-9ad8-422b614443c8/gift-box-builder-1-434/assets/easy-bundle-sdk.js' }
                ];
                const sdkRuntime = SDK_RUNTIME_RULES.find((rule) => rule.match(bundleType));

                const assets = [
                    {   id: 'gbb-sdk-template-css-' + bundleDesignTemplate,
                        tag: 'link',
                        attrs: { href: templateCss, rel: 'stylesheet', media: 'all', className: 'gbb-sdk-template-css' },
                        onload: (el) => el.media = 'all'
                    },
                    {   id: sdkRuntime.id,
                        tag: 'script',
                        attrs: { src: sdkRuntime.url, async: false, crossOrigin: 'anonymous' }
                    },
                    {   id: 'gbb-sdk-template-js-' + bundleDesignTemplate,
                        tag: 'script',
                        // Built-in templates are Shopify assets (CORS-safe); custom templates load from a
                        // CDN without CORS headers, so load them as a plain (non-crossorigin) script.
                        attrs: { src: templateJs, async: false, ...(bundleDesignTemplate === 'CUSTOM_TEMPLATE' ? {} : { crossOrigin: 'anonymous' }) }
                    }
                ];



                loadAssetFiles(assets);
            }catch(err){
                debugConsole("error in importSDKAssets",err)
            }
        }
        window.gbbExtEmbed.f.importSDKAssets = importSDKAssets;

        // Family routing by appLevelMetafieldKey prefix: SDK/PB → SDK loader; else legacy M&M + full-page.
        function importAssets(isDevMode){
            const customSettings = window.easybundles_ext_data?.userData?.customSettings ?? window.easybundle_active_bundle_data?.userData?.customSettings ?? {};
            const loadUnminifiedFiles = isDevMode || (customSettings.loadUnminifiedStorefrontFiles ?? false);

            const bundleConfig = window.shopifyLiquidValuesApp4Ext?.product?.bundleProductConfiguration;
            const bundleKey = bundleConfig?.appLevelMetafieldKey || '';
            const keyPrefix = bundleKey.split('-')[0];
            const seenTemplates = new Set();
            if (keyPrefix === 'SDK') {
                importSDKAssets(undefined, loadUnminifiedFiles);
                if (bundleConfig?.bundleDesignTemplate) {
                    seenTemplates.add(bundleConfig.bundleDesignTemplate);
                }
            } else if(keyPrefix === 'PB'){
                importSDKAssets(undefined, loadUnminifiedFiles);
                if (bundleConfig?.bundleDesignTemplate) {
                    seenTemplates.add(bundleConfig.bundleDesignTemplate);
                }
            } else {
                importMixAndMatchAssets(loadUnminifiedFiles);
                importFullPageAssets(loadUnminifiedFiles);
            }
            // Load assets for every SDK bundle whose upsell rules target this page; dedupe by template
            // (SDK runtime is a singleton; per-offer state lives on window.gbbSdkTemplate.bundles).
            const matchedSdkUpsells = window.easybundles_ext_data?.matchedSdkUpsells ?? {};
            for(const entry of Object.values(matchedSdkUpsells)){
                if(!entry?.bundleDesignTemplate) continue;
                if(seenTemplates.has(entry.bundleDesignTemplate)) continue;
                seenTemplates.add(entry.bundleDesignTemplate);
                importSDKAssets(entry, loadUnminifiedFiles);
            }
            // giftBoxLogicv1 loads on every page — powers the shop-wide widget layer (side cart, upsells).
            importAppEmbedAssets(loadUnminifiedFiles);
        }

        // Overflow recovery: fetch CDN copies of overflowed metafields and write them back to the
        // window globals BEFORE importAssets loads the JS that reads them (spec §5.1).
        async function resolveOverflows(){
            const bundleConfig = window.shopifyLiquidValuesApp4Ext?.product?.bundleProductConfiguration;
            const recomputedFromCDN = await resolveUpsellIndexAndMatches(bundleConfig);

            const fetches = [];
            queueParentSdkConfigFetchIfOverflowed(fetches, bundleConfig);
            queueMatchedUpsellBundleDataFetches(fetches, recomputedFromCDN);
            if (fetches.length === 0) return;
            debugConsole("resolveOverflows => " + fetches.length + " parallel fetch(es)");
            await Promise.all(fetches);
        }

        // Recovers the upsell index (index overflow → CDN copy; ext_data overflow → recompute from the inline
        // index) and rebuilds matchedSdkUpsells, dropping the parent's own offerId. Returns true on recompute.
        async function resolveUpsellIndexAndMatches(bundleConfig){
            const upsellIndexRaw = window.__gbbOverflow?.upsellIndexRaw;
            const forceCdn = isForceCdn();

            let upsellIndex = null;
            if (forceCdn || isOverflowed(upsellIndexRaw)) {
                debugConsole(forceCdn ? "resolveOverflows => gbbForceCdn flag set, fetching upsell index from CDN" : "resolveOverflows => upsell index overflowed, fetching from CDN");
                upsellIndex = await getUpsellIndexFromCDN();
            } else if (Array.isArray(upsellIndexRaw) && !window.easybundles_ext_data?.matchedSdkUpsells) {
                debugConsole("resolveOverflows => matchedSdkUpsells missing (likely ext_data overflow), recomputing from inline index");
                upsellIndex = upsellIndexRaw;
            }
            if (!Array.isArray(upsellIndex)) return false;

            // Empty shell on ext_data overflow — the SDK's getSettings recovery Object.assigns onto it, so this survives.
            window.easybundles_ext_data = window.easybundles_ext_data || {};
            window.easybundles_ext_data.sdkBundleUpsellIndex = upsellIndex;

            const parentOfferId = bundleConfig?.offerId;
            const matchedMap = {};
            for (const bundle of checkIfShouldImportSDKAssets(upsellIndex)) {
                if (!bundle?.offerId) continue;
                if (bundle.offerId === parentOfferId) continue;
                matchedMap[bundle.offerId] = bundle;
            }
            window.easybundles_ext_data.matchedSdkUpsells = matchedMap;
            return true;
        }

        // SDK/PB parent config overflow → fetch the per-offer backup and overwrite _bundleData (FPB self-resolves).
        function queueParentSdkConfigFetchIfOverflowed(fetches, bundleConfig){
            const keyPrefix = (bundleConfig?.appLevelMetafieldKey || '').split('-')[0];
            const keys = ["SDK", "PB"];
            if (!keys.includes(keyPrefix)) return;
            if (!isForceCdn() && !isOverflowed(window.easybundle_active_bundle_data?._bundleData)) return;

            fetches.push(
                getSdkBundleDataFromCDN(bundleConfig?.offerId).then(function(fresh){
                    if (fresh && window.easybundle_active_bundle_data) {
                        window.easybundle_active_bundle_data._bundleData = fresh;
                    }
                })
            );
        }

        // Backfill per-offer bundleData on matched upsells (sentinel at write time, or missing after a recompute).
        function queueMatchedUpsellBundleDataFetches(fetches, recomputedFromCDN){
            const matchedSdkUpsells = window.easybundles_ext_data?.matchedSdkUpsells ?? {};
            const shouldHaveBundleData = window.easybundles_ext_data?.userFlags?.shouldGetBundleDataForWidgets !== false;
            const forceCdn = isForceCdn();
            for (const [offerId, entry] of Object.entries(matchedSdkUpsells)) {
                const isSentinel = isOverflowed(entry?.bundleData);
                const isMissingAfterRecompute = recomputedFromCDN && shouldHaveBundleData && !entry?.bundleData;
                if (!isSentinel && !isMissingAfterRecompute && !forceCdn) continue;

                fetches.push(
                    getSdkBundleDataFromCDN(offerId).then(function(fresh){
                        if (fresh) matchedSdkUpsells[offerId].bundleData = fresh;
                    })
                );
            }
        }

        // Phases: initializeShopifyValues (sync seed, sentinels pass) → resolveOverflows (CDN) → importAssets.
        async function initialize(){
            const urlParams = new URLSearchParams(window.location.search);
            const isDevMode = urlParams.get('dev') == 'true';
            const isDebugMode = urlParams.get('debug') == 'true';
            if (isDebugMode) { debugger; }

            initializeShopifyValues();
            await resolveOverflows();
            importAssets(isDevMode);
        }
        initialize();
    })();



